function storySeen(){ META.story=META.story||{}; return META.story; }
function storyUnlockedIdx(){ return metaRankIdx(); }
/* True once a dispatch is available to read, whether it got there by rank or
   by whatever it is keyed to. */
function storyUnlocked(i){
  const d=STORY[i]; if(!d) return false;
  if(metaRankIdx()>=d.r) return true;
  return !!(d.trig && d.trig());
}
/* Called after a rank-up or a match. Returns the dispatch to show, or null.
   Strictly sequential: the first unseen dispatch that has not unlocked yet
   blocks everything after it, so the arc is always read in order — a trigger
   only ever moves a dispatch EARLIER within its own turn in the queue, never
   ahead of an older one still waiting on rank. */
function storyPending(){
  const s=storySeen();
  for(let i=0;i<STORY.length;i++){
    if(s['d'+i]) continue;
    return storyUnlocked(i)? STORY[i] : null;
  }
  return null;
}
function storyMarkSeen(i){ storySeen()['d'+i]=1; metaSave(); storyRefreshBadge(); }

/* Dispatches belong in the mailbox, not in a compulsory modal queue. The old
   post-match flow reopened the next unlocked dispatch 260 ms after every
   ACKNOWLEDGE. On devices where the card failed to composite, its fixed
   full-screen backdrop was invisible but still intercepted every menu tap.
   A visible badge and one toast preserve the narrative reward without ever
   taking control away from the player. */
/* One number for the mailbox dot. Anything else that becomes unread mail —
   release notes, friend requests — adds its term HERE and nowhere else, so no
   two features ever have to edit the same line of storyRefreshBadge(). */
function inboxUnreadCount(){ return storyUnreadCount()+inboxUnreadUpdates()+inboxUnreadFriends(); }
/* The UPDATES tab has no count element: index.html only gave one to DISPATCHES.
   Create it once here rather than asking for a shell edit — an OTA bundle is
   scripts only (boot.js replaces sources, never index.html or the stylesheet),
   so a badge that lives in the markup can never reach a device that has already
   shipped, and one built in JS can. Same class as the dispatch badge, so it
   inherits the styling that is already on disk. */
function inboxUpdTabCount(){
  const t=document.getElementById('inboxTab-updates'); if(!t) return null;
  let c=t.querySelector('.tabCount');
  if(!c){
    c=document.createElement('span');
    c.className='tabCount'; c.id='inboxUpdTabCount';
    c.setAttribute('aria-hidden','true');
    t.appendChild(c);
  }
  return c;
}
/* THE MAILBOX LOST ITS COUNTS. Replacing the inbox tab strip with one scrolling
   page of .sHead sections deleted #inboxTabCount and #inboxTab-updates, so both
   badge writes above became no-ops: the mailbox tile still said "4 unread" and
   nothing inside told you WHERE they were. Rebind the counts to the section
   heading that sits directly above each list — the same information, attached
   to the thing it describes. Built in JS for the same OTA reason as above. */
function inboxSectionCount(listId){
  const list=document.getElementById(listId); if(!list) return null;
  let h=list.previousElementSibling;
  while(h&&!h.classList.contains('sHead')) h=h.previousElementSibling;
  if(!h) return null;
  let c=h.querySelector('.sHeadCount');
  if(!c){
    c=document.createElement('span');
    c.className='tabCount sHeadCount';
    c.setAttribute('aria-hidden','true');
    h.appendChild(c);
  }
  return c;
}
function storyRefreshBadge(){
  /* The mailbox is the notification surface — the Dossier no longer carries a
     dispatch badge because it no longer carries dispatches. A toast that fires
     while the player is mid-match is a notification you can miss; a badge is
     not. */
  const unread=inboxUnreadCount();
  for(const id of ['inboxBtn','inboxHudBtn']){
    const i=document.getElementById(id); if(!i) continue;
    i.classList.toggle('pendingDispatch',unread>0);
    i.setAttribute('aria-label',unread?('Mailbox, '+unread+' unread transmission'+(unread>1?'s':'')):'Mailbox');
  }
  /* Per-tab counts name only their own pane. The tile above is the whole
     mailbox so it carries the sum, but a DISPATCHES badge reading 13 over a
     list of 12 dispatches and one release note is simply wrong — a badge has to
     agree with what is under it. */
  const setCount=(el,n)=>{ if(!el) return;
    el.textContent=n>99?'99+':String(n); el.classList.toggle('on',n>0); };
  setCount(document.getElementById('inboxTabCount')||inboxSectionCount('inboxDispatches'),storyUnreadCount());
  setCount(inboxUpdTabCount()||inboxSectionCount('inboxUpdates'),inboxUnreadUpdates());
}
/* Unlocked and not yet read. storyPending() stops at the first LOCKED dispatch
   because the arc is strictly sequential; the badge wants the true unread count
   of everything actually readable right now, which is not the same number. */
function storyUnreadCount(){
  const seen=storySeen(); let n=0;
  for(let k=0;k<STORY.length;k++) if(!seen['d'+k] && storyUnlocked(k)) n++;
  return n;
}

/* The unlock condition, in the player's words. The mailbox archive is the only
   caller now that the Dossier is a faction codex and nothing else. */
function storyLockHint(d){
  const r=RANKS[d.r];
  return 'Reach '+r.em+' '+r.nm+(d.trig&&d.hint? '  ·  '+d.hint : '');
}

/* ---------- MAILBOX ----------
   Everything addressed to the player, in one place, including the sealed tail
   of the arc. The mailbox owns dispatches outright: the whole 27-entry archive
   lives here, unread first, then read, then the CLASSIFIED entries the player
   has not earned yet. Friend requests and messages declare themselves as
   pending so the screen does not silently change shape when social ships. */
function renderInbox(){
  const g=document.getElementById('inboxDispatches');
  if(g){
    const seen=storySeen();
    const rows=[];
    for(let i=0;i<STORY.length;i++){
      const d=STORY[i], readable=storyUnlocked(i), read=!!seen['d'+i];
      rows.push({i,d,read,locked:!readable&&!read});
    }
    /* Unread OLDEST first: this arc is authored sequentially (see the header of
       this file) and the old `b.i-a.i` served the newest unread first, so a
       player who banked four dispatches read the war backwards. Read mail is
       newest-first like any mailbox; the sealed archive keeps canonical order. */
    const bucket=r=>r.locked?2:r.read?1:0;
    rows.sort((a,b)=>bucket(a)-bucket(b) || (bucket(a)===1 ? b.i-a.i : a.i-b.i));
    g.innerHTML=rows.map(r=>r.locked
      ? '<div class="inboxItem inboxLog locked">'
        +'<span class="inboxDot" aria-hidden="true"></span>'
        +'<span class="inboxTx"><b>CLASSIFIED</b><span>'+storyLockHint(r.d)+'</span></span>'
        +'<span class="inboxMeta">🔒</span></div>'
      : '<button type="button" class="inboxItem'+(r.read?'':' unread')+'" data-i="'+r.i+'">'
        +'<span class="inboxDot" aria-hidden="true"></span>'
        +'<span class="inboxTx"><b>'+r.d.ttl+'</b><span>'+r.d.from+'</span></span>'
        +'<span class="inboxMeta">'+(r.read?'READ':'NEW')+'</span></button>').join('');
    /* Locked rows carry no data-i and must not bind — a sealed dispatch is not
       a tap target. */
    g.querySelectorAll('.inboxItem[data-i]').forEach(el=>{
      const go=()=>{ showDispatch(STORY[+el.dataset.i]); };
      if(typeof mfBindTap==='function') mfBindTap(el,go); else el.addEventListener('pointerdown',go);
    });
    /* Replaces the unreachable "No transmissions yet" empty state — three
       dispatches are already unlocked at rank 0, so that string never showed.
       This carries the progression the Dossier used to own. */
    /* Create-if-missing, same OTA reasoning as inboxUpdTabCount above: the
       redesign that turned the mailbox into one scrolling page dropped
       #inboxDispHead from the shell, so this whole block became silently dead
       and the player lost every trace of arc progression — the Dossier had
       already handed that job over. */
    let hd=document.getElementById('inboxDispHead');
    if(!hd&&g&&g.parentNode){
      hd=document.createElement('div'); hd.id='inboxDispHead';
      g.parentNode.insertBefore(hd,g);
    }
    if(hd){
      const open=rows.filter(r=>!r.locked).length, unread=storyUnreadCount();
      hd.textContent='📡 '+open+' of '+STORY.length+' declassified'
        +(unread? '  ·  '+unread+' unread' : '');
    }
  }
  /* Four states, cache-driven, synchronous — renderInbox() runs mid-match. */
  renderInboxFriends();
  /* One network fill per open (45s window inside), never a poll, never awaited. */
  inboxFriendsRefresh(false);
  const m=document.getElementById('inboxMessages');
  if(typeof mfSocialRenderInboxMessages==='function') mfSocialRenderInboxMessages();
  else if(m) m.innerHTML='<div class="inboxEmpty">Open Social Command to check direct-chat availability.</div>';
  renderInboxUpdates();
  renderInboxNews();
  storyRefreshBadge();
  /* mfBindTabs is idempotent — it guards every button with dataset.mfTapBound
     and the root with dataset.mfTabsBound — so re-binding on every open is safe
     and keeps working if the shell was replaced by an OTA patch. */
  if(typeof mfBindTabs==='function') mfBindTabs(document.getElementById('inboxScr'),'dispatches');
}
/* The update history this device actually received — written by initUpdater as
   each release starts for the first time. A local log rather than a changelog
   fetched from the server, so it stays truthful offline and after a rollback.

   Every row is a real mail item, not a caption. The notes body runs to ~900
   characters and .inboxTx span clamps to one ellipsised line, so a row that
   could not be opened was a release log you could see and not read. */
function updateLogRows(){ return (typeof updLogRead==='function')? updLogRead() : []; }
/* Strictly `read===false`, never `!read`. Entries written before this feature
   existed carry no read flag at all, and treating those as unread would greet
   every upgrading player with a badge full of releases they installed months
   ago. An entry that was never announced is history, not news; only the writer
   that can announce one marks it. */
function inboxUnreadUpdates(){ return updateLogRows().filter(e=>e.read===false).length; }
function renderInboxUpdates(){
  const g=document.getElementById('inboxUpdates'); if(!g) return;
  /* Notes are publisher copy, not player input, but they land in innerHTML and
     an unescaped & or < in a changelog would silently eat the rest of a row. */
  const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  /* The version actually running: on a patched build the bundle carries its own
     updater.js with the bumped APP_VERSION, and after a rollback APP_VERSION is
     once again what is executing. Both true, so this needs no patch state. */
  const cur=(typeof APP_VERSION!=='undefined'&&APP_VERSION)||'';
  const rows=updateLogRows();
  if(!rows.length){
    g.innerHTML='<div class="inboxEmpty">No updates installed on this device yet'
      +(cur?' — running v'+cur:'')+'.</div>';
    return;
  }
  /* No slice: the log is already capped at 40 by updLogPost, and rendering a
     shorter window than the badge counts would put a number on the tab that
     nothing under it explains. */
  g.innerHTML=rows.map((e,i)=>{
    const d=new Date(e.at||0);
    const when=(!e.at||isNaN(d.getTime()))?''
      :d.toLocaleDateString(undefined,{month:'short',day:'numeric'});
    /* Reverted beats running: a rolled-back entry cannot also be what is on the
       device, and initUpdater clears the mark if that version is ever applied
       again. */
    const tag=e.rolledBack?' · reverted':(String(e.version)===cur?' · running now':'');
    const isNew=e.read===false;          // see inboxUnreadUpdates
    return '<button type="button" class="inboxItem inboxUpd'+(isNew?' unread':'')+'" data-u="'+i+'">'
      +'<span class="inboxDot" aria-hidden="true"></span>'
      +'<span class="inboxTx"><b>v'+esc(e.version)+tag+'</b>'
      +'<span>'+esc(e.notes||'Update installed')+'</span></span>'
      +'<span class="inboxMeta">'+(isNew?'NEW':when)+'</span></button>';
  }).join('');
  g.querySelectorAll('.inboxUpd').forEach(el=>{
    const go=()=>inboxOpenUpdate(rows[+el.dataset.u]);
    if(typeof mfBindTap==='function') mfBindTap(el,go); else el.addEventListener('pointerdown',go);
  });
}
/* A release note is mail, so it opens the same transmission card the dispatches
   use — that card scrolls, which is the only thing on this screen that can show
   900 characters. The list underneath is deliberately NOT repainted here: the
   dismiss handler in main.js already redraws the mailbox, and rebuilding a list
   under a live modal is what that handler exists to avoid. */
function inboxOpenUpdate(e){
  if(!e) return;
  if(typeof updLogMark==='function') updLogMark(e.version,{read:true});
  e.read=true;
  /* from/ttl are FIXED strings and never the notes body: storySpeakerVisual and
     storyTransmissionVisual keyword-match those two fields, and a changelog that
     happens to mention the Syndicate must not arrive spoken by Broker Renn. */
  showDispatch({ttl:'BUILD v'+e.version, idx:'RELEASE NOTES',
    from:'MASSFRONT RELEASE CHANNEL · BROADCAST',
    txt:e.notes||'This build was installed on this device.'});
  storyRefreshBadge();
}
/* Newsletters are optional and served from the release channel. A build whose
   channel has no news.json simply says so — it never errors and never blocks. */
let INBOX_NEWS=null;
function renderInboxNews(){
  const g=document.getElementById('inboxNews'); if(!g) return;
  const draw=()=>{
    if(!INBOX_NEWS||!INBOX_NEWS.length){
      g.innerHTML='<div class="inboxEmpty">No newsletters yet. Release notes and briefings will appear here.</div>';
      return;
    }
    g.innerHTML=INBOX_NEWS.slice(0,10).map(n=>
      '<div class="inboxItem inboxLog"><span class="inboxDot" aria-hidden="true"></span>'
      +'<span class="inboxTx"><b>'+String(n.title||'BRIEFING').replace(/</g,'&lt;')+'</b>'
      +'<span>'+String(n.body||'').replace(/</g,'&lt;').slice(0,160)+'</span></span></div>').join('');
  };
  draw();
  if(INBOX_NEWS!==null) return;
  /* Latch the cache ONLY once a request is actually issued. Setting it to []
     above these guards meant a single Inbox open while offline — or before
     updResolveEndpoint had finished — killed newsletters for the rest of the
     session, with no retry when the player came back online. */
  if(typeof netAllowed==='function'&&!netAllowed()) return;
  const base=(typeof updEndpoint==='function'&&updEndpoint())||'';
  if(!base) return;
  INBOX_NEWS=[];
  try{
    /* netFetch, not fetch: it re-checks the offline gate and aborts at 12s. A
       raw fetch hangs forever on a captive portal, which is the exact failure
       src/offline.js exists to prevent. */
    const url=base.replace(/\/[^/]*$/,'/')+'news.json';
    const req=(typeof netFetch==='function')
      ? netFetch(url,{cache:'no-store'}) : fetch(url,{cache:'no-store'});
    req.then(r=>r.ok?r.json():null)
       .then(j=>{ if(j&&Array.isArray(j.items)){ INBOX_NEWS=j.items; draw(); } })
       .catch(()=>{});
  }catch(e){}
}

/* ---------- FRIENDS ----------
   The mailbox's friends section, in four states and nothing else:

     signed-out  one line plus a door into the account panel. Friends are the
                 only part of this game that needs an account, so this is the
                 ONLY place that ever asks for one, and it asks once, quietly.
     offline     a quiet line. Never an error wall: being on a train is not a
                 fault condition, and a red box on the mailbox of an offline
                 player is a bug report waiting to happen.
     empty       an invitation. Signed in, reachable, nobody there yet.
     data        incoming requests first (they are the thing with a decision
                 attached), then the friends list.

   renderInboxFriends() is SYNCHRONOUS and reads only INBOX_FRIENDS, because
   renderInbox() is called mid-match from the HUD button and an await there
   would paint an empty overlay over the battlefield for a network round trip.
   The network half is inboxFriendsRefresh(), which repaints when it lands.

   NOTHING here may block play. Every socialX() wrapper resolves — it never
   rejects — and every one of them is called through a typeof guard, so a
   bundle without authportal.js renders the signed-out state and stops. */
let INBOX_FRIENDS={signedIn:false,loaded:false,busy:false,at:0,
                   code:'',msg:'',gate:'ok',friends:[],incoming:[]};
/* One fill per inbox open, never a poll. renderInbox() also runs when a
   dispatch is dismissed and when the HUD button reopens the overlay, so the
   window below is what turns "render again" into "do not ask the server
   again". A failed attempt latches the same window: a device with no signal
   must not retry once per repaint. */
const INBOX_FRIENDS_MIN_MS=45000;

/* Usernames are UGC and are written with textContent EVERYWHERE below — that
   is the escaping, and it is why this section builds elements instead of
   joining an HTML string like the dispatch list above does. This helper does
   not escape (escaping before textContent would show a player the literal
   text "&amp;"); it only strips the control and bidi-override characters that
   a text node would otherwise honour, and clamps the length so one very long
   name cannot push the ACCEPT button off the row. */
function inboxFriendsName(f){
  let n=String((f&&f.username)||'');
  let out='';
  for(let i=0;i<n.length;i++){
    const c=n.charCodeAt(i);
    if(c<32||c===127||(c>=0x202a&&c<=0x202e)||(c>=0x2066&&c<=0x2069)) continue;
    out+=n.charAt(i);
  }
  out=out.trim();
  if(out.length>32) out=out.slice(0,31)+'…';
  return out||'Commander';
}
/* The whole state machine, pure, so it can be tested without a DOM. Data beats
   everything: a cache that already holds friends keeps showing them when a
   later refresh fails, because a list that empties itself the moment a tunnel
   swallows the signal reads as "your friends were deleted". */
function inboxFriendsState(c){
  if(!c||!c.signedIn) return 'signed-out';
  if((c.friends&&c.friends.length)||(c.incoming&&c.incoming.length)) return 'data';
  if(c.loaded) return 'empty';
  return c.code?'offline':'empty';
}
/* Zero unless a real server answered with real requests, which is what keeps
   the mailbox dot honest on a build with no backend at all. */
function inboxUnreadFriends(){
  /* Live session, not the cache. The cached flag is only refreshed by
     renderInboxFriends(), and sign-out does not re-render the inbox - so
     trusting it left a friend-request badge lit after sign-out, pointing at
     requests the player can no longer see. */
  if(typeof mfSocialSignedIn!=='function'||!mfSocialSignedIn()) return 0;
  const c=INBOX_FRIENDS;
  return (c&&c.loaded&&c.incoming)?c.incoming.length:0;
}
/* The .sHead directly above a list is where inboxSectionCount() hangs its
   badge (see ~line 240): a list created without one silently loses its count
   forever, which is exactly the defect that killed the dispatch counts when
   the mailbox was rebuilt as one scrolling page. So the create-if-missing path
   creates the HEADING TOO, and puts the pair where the shipped shell has it —
   above MESSAGES — rather than appending it to the bottom of the page. */
function inboxSHeadAbove(el){
  let h=el?el.previousElementSibling:null;
  while(h&&!(h.classList&&h.classList.contains('sHead'))) h=h.previousElementSibling;
  return h;
}
function inboxFriendsHost(){
  let g=document.getElementById('inboxFriends');
  if(g) return g;
  const scr=document.querySelector('#inboxScr .inboxScroll')||document.getElementById('inboxScr');
  if(!scr) return null;
  const h=document.createElement('div');
  h.className='sHead'; h.style.marginTop='14px'; h.textContent='FRIEND REQUESTS';
  g=document.createElement('div'); g.id='inboxFriends';
  const anchor=inboxSHeadAbove(document.getElementById('inboxMessages'));
  if(anchor&&anchor.parentNode===scr){ scr.insertBefore(h,anchor); scr.insertBefore(g,anchor); }
  else { scr.appendChild(h); scr.appendChild(g); }
  return g;
}
function inboxFriendsLine(txt){
  const d=document.createElement('div');
  d.className='inboxEmpty';
  d.textContent=txt;
  return d;
}
/* 44px minimum on every tap target, set inline: this file cannot add a rule to
   ui.css, and an OTA bundle is scripts only, so a class that does not already
   exist on disk would reach nobody. min-height beats a class height. */
function inboxFriendsBtn(label,fn){
  const b=document.createElement('button');
  b.type='button';
  b.className='mbtn alt';
  b.textContent=label;
  b.style.minHeight='44px'; b.style.minWidth='44px';
  b.style.padding='0 12px'; b.style.fontSize='10px'; b.style.flex='0 0 auto';
  if(typeof mfBindTap==='function') mfBindTap(b,fn);
  else b.addEventListener('click',fn);
  return b;
}
function inboxFriendsToast(m){
  if(typeof toast==='function'){ try{ toast(m); }catch(e){} }
}
function inboxFriendsOpenAccount(trigger){
  if(typeof sfx==='function'){ try{ sfx('ui'); }catch(e){} }
  if(typeof apOpen==='function'){ try{ apOpen(trigger||null); return; }catch(e){} }
  if(typeof showFrontScreen==='function'){ try{ showFrontScreen('profileScr'); }catch(e){} }
}
/* One row per person. b is the username and it is set with textContent, so a
   name of "<script>x</script>" arrives as thirty-odd inert characters. */
function inboxFriendsRow(f,sub){
  const row=document.createElement('div');
  row.className='inboxItem inboxLog';
  row.style.minHeight='44px';
  const dot=document.createElement('span');
  dot.className='inboxDot'; dot.setAttribute('aria-hidden','true');
  row.appendChild(dot);
  const tx=document.createElement('span');
  tx.className='inboxTx';
  const b=document.createElement('b');
  b.textContent=inboxFriendsName(f);
  const s=document.createElement('span');
  s.textContent=sub||'';
  tx.appendChild(b); tx.appendChild(s);
  row.appendChild(tx);
  return row;
}
function inboxFriendsRequestRow(r){
  const row=inboxFriendsRow(r,'wants to be friends');
  row.className='inboxItem unread';
  const acts=document.createElement('span');
  acts.className='inboxMeta';
  acts.style.display='flex'; acts.style.gap='6px'; acts.style.alignItems='center';
  acts.appendChild(inboxFriendsBtn('ACCEPT',()=>inboxFriendsRespond(r,true)));
  acts.appendChild(inboxFriendsBtn('DECLINE',()=>inboxFriendsRespond(r,false)));
  row.appendChild(acts);
  return row;
}
/* Optimistic only AFTER the server agrees. Dropping the row on tap and putting
   it back on failure is worse than a 300ms wait: the row that reappears looks
   like a second request from the same person. */
function inboxFriendsRespond(r,accept){
  const c=INBOX_FRIENDS;
  if(!r||c.busy) return;
  if(typeof socialRespond!=='function'){
    inboxFriendsToast('Friends are not available in this build.');
    return;
  }
  c.busy=true;
  Promise.resolve(socialRespond(r.id||r.username,accept)).then(res=>{
    c.busy=false;
    if(res&&res.ok){
      c.incoming=(c.incoming||[]).filter(x=>x!==r);
      if(accept) c.friends=(c.friends||[]).concat([{id:r.id,username:r.username}]);
      inboxFriendsToast(accept?('Friend request accepted — '+inboxFriendsName(r))
                              :'Friend request declined');
    }else{
      const gate=(typeof mfSocialGate==='function')?mfSocialGate(res):'ok';
      if(gate!=='ok') c.gate=gate;
      inboxFriendsToast((res&&res.message)||'Could not reach the friends service.');
    }
    renderInboxFriends();
    if(typeof storyRefreshBadge==='function') storyRefreshBadge();
  }).catch(()=>{ c.busy=false; });
}
/* The network half. Refuses in every case where a request would be pointless
   or rude — signed out, offline, no wrapper, already asked inside the window —
   and it is a plain function, not an async one, so renderInbox() stays
   synchronous when it calls it. */
function inboxFriendsRefresh(force){
  const c=INBOX_FRIENDS;
  if(c.busy) return false;
  if(typeof socialFriends!=='function') return false;
  if(typeof mfSocialSignedIn!=='function'||!mfSocialSignedIn()) return false;
  if(typeof netAllowed==='function'&&!netAllowed()){
    /* Not an error and not a retry: mark the cache offline and repaint the
       quiet line. No request is issued, so nothing to time out. */
    if(!c.loaded){ c.code='offline'; c.at=Date.now(); renderInboxFriends(); }
    return false;
  }
  const now=Date.now();
  if(!force&&c.at&&(now-c.at)<INBOX_FRIENDS_MIN_MS) return false;
  c.busy=true; c.at=now;
  Promise.resolve(socialFriends()).then(res=>{
    c.busy=false;
    if(res&&res.ok){
      c.friends=res.friends||[]; c.incoming=res.incoming||[];
      c.loaded=true; c.code=''; c.msg=''; c.gate='ok';
    }else{
      c.code=(res&&res.code)||'server';
      c.msg=(res&&res.message)||'';
      c.gate=(typeof mfSocialGate==='function')?mfSocialGate(res):'ok';
    }
    renderInboxFriends();
    if(typeof storyRefreshBadge==='function') storyRefreshBadge();
  }).catch(()=>{ c.busy=false; });
  return true;
}
function renderInboxFriends(){
  const g=inboxFriendsHost(); if(!g) return;
  const c=INBOX_FRIENDS;
  c.signedIn=(typeof mfSocialSignedIn==='function')?mfSocialSignedIn():false;
  /* Signing out has to empty the cache, not just hide it — otherwise the next
     player on this device sees the previous player's friends for one frame. */
  if(!c.signedIn){ c.loaded=false; c.friends=[]; c.incoming=[]; c.code=''; c.gate='ok'; }
  while(g.firstChild) g.removeChild(g.firstChild);
  const st=inboxFriendsState(c);
  if(st==='signed-out'){
    g.appendChild(inboxFriendsLine(
      'Sign in to add friends by username and see who wants to squad up. '+
      'Everything else in the game works exactly the same without an account.'));
    const b=inboxFriendsBtn('OPEN ACCOUNT',()=>inboxFriendsOpenAccount(b));
    b.style.marginTop='8px';
    g.appendChild(b);
  }else if(st==='offline'){
    /* A gate is not a network failure: an account that has not verified its
       email needs a door, not an apology. */
    const nudge=(typeof mfSocialNudge==='function')?mfSocialNudge(c.gate):null;
    if(nudge){
      g.appendChild(inboxFriendsLine(nudge.text));
      if(nudge.cta){
        const b=inboxFriendsBtn(nudge.cta,()=>{ if(nudge.act) nudge.act(b); });
        b.style.marginTop='8px';
        g.appendChild(b);
      }
    }else{
      g.appendChild(inboxFriendsLine(
        'Friends are offline right now — this list fills in the next time '+
        'you open the mailbox with a connection.'));
    }
  }else if(st==='empty'){
    g.appendChild(inboxFriendsLine(c.loaded
      ? 'No friend requests. Add a commander by their exact username to send one.'
      : 'Checking for friend requests…'));
  }else{
    for(const r of (c.incoming||[])) g.appendChild(inboxFriendsRequestRow(r));
    if((c.friends||[]).length){
      const h=document.createElement('div');
      h.className='sHead'; h.style.marginTop='10px'; h.textContent='FRIENDS';
      g.appendChild(h);
      for(const f of c.friends) g.appendChild(inboxFriendsRow(f,'friend'));
    }
  }
  /* Same badge helper the dispatch and update lists use, on the heading this
     list actually sits under. */
  if(typeof inboxSectionCount==='function'){
    const cnt=inboxSectionCount('inboxFriends');
    if(cnt){
      const n=inboxUnreadFriends();
      cnt.textContent=n>99?'99+':String(n);
      cnt.classList.toggle('on',n>0);
    }
  }
}
/* ---------- END FRIENDS ---------- */

/* The portraits are canonical command identities, not interchangeable avatars.
   A Nova survey memo still travels through Captain Kai's authenticated command
   channel; its authored service remains visible separately in `from`. This is
   important for reports about the Brood: mentioning a hive must never turn a
   Nova xenobiology report into a message spoken by the Brood Sovereign. */
function storySpeakerVisual(d){
  const source=((d&&d.from)||'').toLowerCase(), title=((d&&d.ttl)||'').toLowerCase();
  /* A changelog is the only thing in this card that is not in-fiction. It must
     not arrive signed by Captain Kai — which is what the default below would do
     — but it also cannot invent a portrait key, because #dispPortrait has no
     onerror and a missing faction image renders as a broken-image glyph. Keep
     the Nova art as the channel avatar and say plainly who is talking. */
  if(source.includes('release channel'))
    return {key:'nova',name:'MASSFRONT',commander:'RELEASE CHANNEL',
      src:'./assets/factions/nova_192.jpg',alt:'MASSFRONT release channel'};
  let key='nova';
  /* Machine Ascendancy is the Coalition's doctrinal name, not the Red
     Ascendancy. Test it first so the shared word cannot select Vex. */
  if(source.includes('machine ascendancy')||source.includes('syndicate')||source.includes('renn')) key='syndicate';
  else if(source.includes('red ascendancy')||source.includes('legion')||source.includes('ascendancy')||source.includes('vex')) key='ascendancy';
  else if(source.includes('brood sovereign')||source.includes('source: the brood')||
          source.includes('infestation swarm')||source.includes('swarm channel')) key='horde';
  else if(title.includes('faction profile: red ascendancy')) key='ascendancy';
  const A=(typeof FACART!=='undefined'&&FACART[key])||{
    nm:key==='horde'?'Umbral Brood':key.toUpperCase(),
    cdr:key==='nova'?'Captain Elara Kai':key==='ascendancy'?'Lord Darion Vex':
        key==='syndicate'?'Broker Lys Renn':'The Brood Sovereign'
  };
  /* The active campaign channel belongs to the commander the player selected,
     so a Holt or Vale doctrine must not keep showing Kai. Enemy intercepts and
     general faction dossiers still use their canonical faction speaker. */
  const chosen=key==='nova'&&typeof storyCampaignActiveId!=='undefined'&&storyCampaignActiveId&&
    typeof playerCommanderDef==='function'?playerCommanderDef():null;
  const commander=chosen?chosen.nm:A.cdr;
  return {key,name:A.nm,commander,
    src:chosen&&typeof commanderPortraitSrc==='function'?commanderPortraitSrc(chosen):'./assets/factions/'+key+'_192.jpg',
    fallback:'./assets/factions/'+key+'_192.jpg',alt:commander+', '+A.nm+' commander portrait'};
}

/* Transmission state is derived from the authored route, never random chrome.
   Players can distinguish an authenticated order, open propaganda, a field
   report and a damaged intercept before reading the paragraph. */
function storyTransmissionVisual(d){
  const route=(((d&&d.from)||'')+' '+((d&&d.ttl)||'')).toLowerCase();
  if(route.includes('urgent')||route.includes('priority'))
    return {mode:'urgent',protocol:'PRIORITY LINK',signal:86,label:'PRIORITY TRAFFIC',mark:'URGENT'};
  if(route.includes('intercept')||route.includes('sigint')||route.includes('decode')||
     route.includes('source unknown')||route.includes('source:')||route.includes('attributed transmission'))
    return {mode:'intercepted',protocol:'INTERCEPT / DECODE',signal:48,label:'SIGNAL INTELLIGENCE',mark:'DEGRADED'};
  if(route.includes('open channel')||route.includes('public channel')||route.includes('public band')||
     route.includes('unscrambled')||route.includes('unencrypted')||route.includes('broadcast'))
    return {mode:'open',protocol:'OPEN BAND',signal:72,label:'PUBLIC TRANSMISSION',mark:'OPEN'};
  if(route.includes('field')||route.includes('report')||route.includes('after-action')||
     route.includes('survey')||route.includes('assessment'))
    return {mode:'field',protocol:'FIELD RELAY',signal:79,label:'FIELD INTELLIGENCE',mark:'FIELD'};
  return {mode:'secure',protocol:'SECURE COMMAND',signal:98,label:'COMMAND BRIEF',mark:'SECURE'};
}

function showDispatch(d){
  if(!d) return;
  const el=document.getElementById('dispatch'); if(!el) return;
  const speaker=storySpeakerVisual(d), tx=storyTransmissionVisual(d), portrait=document.getElementById('dispPortrait');
  if(portrait){
    portrait.onerror=()=>{portrait.onerror=null;if(speaker.fallback)portrait.src=speaker.fallback;};
    portrait.src=speaker.src; portrait.alt=speaker.alt;
  }
  const faction=document.getElementById('dispFaction'); if(faction) faction.textContent=speaker.name;
  const box=el.querySelector('.dispBox');
  if(box){ box.dataset.faction=speaker.key; box.dataset.mode=tx.mode; }
  const who=document.getElementById('dispSpeakerName'); if(who) who.textContent=speaker.commander;
  const protocol=document.getElementById('dispProtocol'); if(protocol) protocol.textContent=tx.protocol;
  const signal=document.getElementById('dispSignal'); if(signal) signal.textContent='LINK '+tx.signal+'%';
  const mark=document.getElementById('dispStateMark'); if(mark) mark.textContent=tx.mark;
  const cls=document.getElementById('dispClass'); if(cls) cls.textContent=tx.label;
  const rail=el.querySelector('.dispSignalRail');
  if(rail) Array.from(rail.children).forEach((bar,i)=>{
    const lit=i<Math.ceil(tx.signal/20);
    bar.style.opacity=lit?(0.25+i*0.16).toFixed(2):'0.08';
  });
  document.getElementById('dispTtl').textContent=d.ttl;
  document.getElementById('dispFrom').textContent=d.from;
  document.getElementById('dispTxt').textContent=d.txt;
  /* This card now also shows release notes, which are not STORY entries. Without
     the guard indexOf returns -1, the header reads "DISPATCH 0 / 27" and
     storyMarkSeen(-1) writes a junk META.story['d-1'] key into the save. */
  const si=STORY.indexOf(d);
  document.getElementById('dispIdx').textContent = si>=0
    ? 'DISPATCH '+(si+1)+' / '+STORY.length : (d.idx||'RELEASE NOTES');
  el.setAttribute('aria-label',speaker.commander+' — '+d.ttl);
  el.style.display='flex';
  el.classList.remove('in'); void el.offsetWidth; el.classList.add('in');
  if(si>=0) storyMarkSeen(si);
  if(typeof sfx==='function') sfx(tx.mode==='urgent'?'alarm':'level');
}
/* Show whatever is owed, one at a time — a player who ranks up twice in a
   session reads two dispatches, not one on top of the other. */
function storyCheck(){
  const d=storyPending();
  storyRefreshBadge();
  if(d&&typeof toast==='function') toast('📡 NEW DISPATCH — check your MAILBOX ✉');
  return d;
}
/* Match-end note for the debrief. META.facWins / losses / weekly.runs are
   already written by the time endgameRecord runs, so a trigger that just
   became true surfaces here instead of waiting for the mailbox toast. */
function storyMatchNote(){
  storyRefreshBadge();
  const d=storyPending();
  if(!d) return null;
  return {ttl:d.ttl, from:d.from};
}
/* renderDossier() lived here. The Dossier is the faction codex now and nothing
   else; the whole dispatch archive, sealed entries included, is renderInbox()
   above. Its lock-hint string survives as storyLockHint(). */

/* ============================================================================
   CAMPAIGN PROLOGUE — a playable front door for first-time commanders
   ----------------------------------------------------------------------------
   This is deliberately a takeover of Operations rather than a second mission
   menu. The prologue launches the proven Training Operation or pre-fills the
   real Battle Setup screen, so every BEGIN button reaches playable rules and
   none of the PRE-ALPHA story cards pretend that an unbuilt scripted mission
   exists. Faction keys stay identical to ai.js/save data.
   ============================================================================ */
const STORY_CAMPAIGN_PROLOGUE=[
  {id:'orientation',code:'P-00',ttl:'FIELD ORIENTATION',fac:'nova',map:'vanguard',theme:'verdant',
   threat:'COMMAND SIMULATION',goal:'training',diff:0,time:0,inf:false,defense:1,scale:'standard',
   objective:'Deploy the Commander, establish power and production, build a defensive line, then lead a formation through its first attack order.',
   reward:'150 CORES · COMMAND CERTIFICATION',unlock:'start',complete:'training'},
  {id:'mosswatch-breach',code:'P-01',ttl:'MOSSWATCH BREACH',fac:'horde',player:'nova',map:'aelos_north_small',theme:'verdant',
   threat:'BROOD SWARM',goal:'purge',diff:0,time:720,inf:true,defense:1,scale:'compact',script:'mosswatch',
   objective:'Hold the abandoned causeway, recover the survey archive, and seal the bleeding reality wounds before their first organized Tidecaster assault reaches the landing site.',
   reward:'MATCH XP · CORES · +15% RESEARCH · FIELD CACHE',unlock:'training'},
  {id:'first-breach',code:'P-02',ttl:'THE FIRST BREACH',fac:'ascendancy',map:'vanguard',theme:'verdant',
   threat:'CRIMSON DOMINION',goal:'annihilate',diff:0,time:0,inf:false,defense:1,scale:'standard',
   objective:'Fortify the valley approach, preserve the Commander, and destroy the Dominion command unit before its armour column breaks your line.',
   reward:'MATCH XP · CORES · CRIMSON SERVICE RECORD',unlock:'mosswatch-breach',complete:'legion',legacyComplete:true},
  {id:'coalition-intercept',code:'P-03',ttl:'COALITION INTERCEPT',fac:'syndicate',map:'highland',theme:'arctic',
   threat:'SYNDICATE COALITION',goal:'domination',diff:1,time:600,inf:false,defense:0,scale:'standard',
   objective:'Take and hold Nordhall Frontline Shelf resource lanes while Coalition energy cadres probe the flanks and contest the ice-shelf works.',
   reward:'MATCH XP · CORES · SYNDICATE SERVICE RECORD',unlock:'first-breach',complete:'syndicate',legacyComplete:true},
  {id:'ground-remembers',code:'P-04',ttl:'THE GROUND REMEMBERS',fac:'horde',map:'crater',theme:'ashland',
   threat:'BROOD SWARM',goal:'purge',diff:1,time:900,inf:true,defense:1,scale:'large',
   objective:'Establish overlapping fields of fire in Vespera Caldera Nests, burn out every living nest, and survive the Brood organisms defending the infestation.',
   reward:'MATCH XP · CORES · BROOD SERVICE RECORD',unlock:'coalition-intercept',complete:'horde',legacyComplete:true},
];

function storyCampaignComplete(m){
  if(m.complete==='training') return !!(META.tutorial&&META.tutorial.done);
  const missions=META.campaign&&META.campaign.missions;
  if(missions&&missions[m.id]&&missions[m.id].wins>0)return true;
  /* Preserve completion earned before authored mission records existed. The
     new Mosswatch slice deliberately has no legacy shortcut: it must actually
     be played once, while the three older prologue cards retain prior clears. */
  return !!(m.legacyComplete&&m.complete&&(META.facWins||{})[m.complete]>0);
}
function storyCampaignUnlocked(m,i){
  if(i===0||storyCampaignComplete(m)) return true;
  return storyCampaignComplete(STORY_CAMPAIGN_PROLOGUE[i-1]);
}
function storyCampaignProgress(){
  const states=STORY_CAMPAIGN_PROLOGUE.map((m,i)=>({
    done:storyCampaignComplete(m),open:storyCampaignUnlocked(m,i)
  }));
  let current=states.findIndex(s=>s.open&&!s.done);
  if(current<0) current=STORY_CAMPAIGN_PROLOGUE.length-1;
  return {states,current,done:states.filter(s=>s.done).length};
}
function storyCampaignEnsureOps(){
  /* Only the five-mission Prologue is live. The longer faction arcs remain
     roadmap material in the Dossier and are never presented as playable. */
  const root=document.getElementById('opsScr'),tabs=document.getElementById('opsTabs');
  if(!root||!tabs) return;
  if(!document.getElementById('opsTab-campaign')){
    const tab=document.createElement('button');
    tab.className='screenTabBtn'; tab.id='opsTab-campaign'; tab.type='button';
    tab.setAttribute('role','tab'); tab.dataset.mfTab='campaign';
    tab.setAttribute('aria-controls','opsPane-campaign');
    tab.innerHTML='<span class="tabGlyph">◇</span><span>CAMPAIGN</span>';
    tabs.insertBefore(tab,tabs.firstElementChild);
  }
  if(!document.getElementById('opsPane-campaign')){
    const pane=document.createElement('section');
    pane.className='setupCard mfTabPanel storyCampaignPane';
    pane.id='opsPane-campaign'; pane.setAttribute('role','tabpanel');
    pane.setAttribute('aria-labelledby','opsTab-campaign'); pane.dataset.mfPanel='campaign';
    const scroll=root.querySelector('.opsScroll'),first=scroll&&scroll.firstElementChild;
    if(scroll) scroll.insertBefore(pane,first||null);
  }
  /* A new commander sees the authored starting path first. Returning players
     keep whichever Operations category they last selected. */
  if(typeof MF_TAB_STATE!=='undefined'&&!MF_TAB_STATE.opsScr&&!(META.matches||0))
    MF_TAB_STATE.opsScr='campaign';
}
function storyCampaignFac(m){
  return (typeof facArt==='function'&&facArt(m.fac))||FACART.nova;
}
function storyCampaignPortrait(a){
  return '<img src="./assets/factions/'+a.id+'_192.jpg" alt="'+a.cdr+', '+a.nm+' commander" '
    +'onerror="this.style.visibility=\'hidden\'">';
}
const STORY_CAMPAIGN_KEY_ART={
  nova:'data:image/webp;base64,',
  ascendancy:'data:image/webp;base64,',
  syndicate:'data:image/webp;base64,',
  horde:'data:image/webp;base64,'
};
function storyCampaignKeyArt(fac){
  return STORY_CAMPAIGN_KEY_ART[fac]||STORY_CAMPAIGN_KEY_ART.nova;
}
function storyCampaignRender(){
  const pane=document.getElementById('opsPane-campaign'); if(!pane) return;
  const progress=storyCampaignProgress();
  let missions='';
  STORY_CAMPAIGN_PROLOGUE.forEach((m,i)=>{
    const S=progress.states[i],A=storyCampaignFac(m),map=MAPDEFS[m.map]||{nm:m.map,ds:''},
          haz=(typeof mapHazardDef==='function'&&mapHazardDef(m.map))||
              (typeof MAPHAZ!=='undefined'&&MAPHAZ[m.map])||{em:'◇',nm:'FIELD CONDITIONS'},
          state=S.done?'COMPLETE':S.open?(i===progress.current?'CURRENT':'AVAILABLE'):'LOCKED',
          unlock=i?('Complete '+STORY_CAMPAIGN_PROLOGUE[i-1].code+' · '+STORY_CAMPAIGN_PROLOGUE[i-1].ttl):'';
    missions+='<article class="storyCampaignMission '+state.toLowerCase()+'" style="--cf:'+A.col+';--cf2:'+A.col2+'">'
      +'<div class="storyCampaignKeyArt"><img src="'+storyCampaignKeyArt(m.fac)+'" alt="'+A.nm+' cinematic battlefield">'
        +'<span>'+(typeof facIcon==='function'?facIcon(m.fac,30):'◇')+'</span><small>'+A.nm+'</small></div>'
      +'<div class="storyCampaignMissionBody"><header><div><small>'+m.code+' · PROLOGUE</small><b>'+m.ttl+'</b></div>'
        +'<i class="storyCampaignState">'+state+'</i></header>'
      +'<div class="storyCampaignIntel"><span><em>OBJECTIVE</em>'+m.objective+'</span>'
        +'<span><em>BATTLEFIELD</em>'+map.nm+' · '+haz.em+' '+haz.nm+'</span>'
        +'<span><em>FACTION THREAT</em>'+A.nm+' · '+A.strong+'</span>'
        +'<span class="storyCampaignReward"><em>REWARDS</em>'+m.reward+'</span></div>'
      +(S.open?'<button class="storyCampaignAction" type="button" data-campaign-mission="'+m.id+'">'
          +(S.done?'↻ REPLAY MISSION':'▶ '+(i===0?'BEGIN TRAINING':'BEGIN MISSION'))+'</button>'
        :'<div class="storyCampaignLock">▣ '+unlock+'</div>')
      +'</div></article>';
  });
  const arcs=Object.keys(FACART).map(k=>{
    const A=FACART[k];
    return '<article class="storyCampaignArc" style="--cf:'+A.col+';--cf2:'+A.col2+'">'
      +'<div class="storyCampaignArcHead">'+storyCampaignPortrait(A)
        +'<div><small>'+A.motto+'</small><b>'+A.nm+'</b><span>'+A.cdr+'</span></div></div>'
      +'<div class="storyCampaignArcPath">'+A.arc+'</div><p>'+A.endgoal+'</p></article>';
  }).join('');
  const heroMission=STORY_CAMPAIGN_PROLOGUE[progress.current]||STORY_CAMPAIGN_PROLOGUE[0];
  pane.innerHTML='<section class="storyCampaignHero" style="--campaign-hero:url(&quot;'+storyCampaignKeyArt(heroMission.fac)+'&quot;)"><div><span>PRE-ALPHA · PLAYABLE PROLOGUE</span>'
      +'<h3>HALCYON REACH: FIRST CONTACT</h3><p>Learn the command loop, then meet all three enemy doctrines through live battle rules. '
      +'Acts I–IV below are the campaign direction; only the Prologue ladder is presented as playable today.</p><span class="storyModeReward">+25% XP · ◇ CAMPAIGN COMMAND INTEL ON VICTORY</span></div>'
      +'<div class="storyCampaignCount"><b>'+progress.done+'</b><span>/ '+STORY_CAMPAIGN_PROLOGUE.length+' CLEARED</span></div></section>'
    +'<div class="storyCampaignSection"><span>PROLOGUE MISSION LADDER</span><small>Each deployment uses the real training or battle setup flow.</small></div>'
    +'<div class="storyCampaignLadder">'+missions+'</div>'
    /* The four-faction arcs carousel used to sit here. It rebuilt the Dossier's
       faction cards verbatim — a second copy of another screen, inside the one
       screen whose job is starting matches, and a large share of why this pane
       ran to 2030px against a 254px window. The Dossier is the factions screen;
       this is a pointer to it, not a duplicate of it. */
    +'<button class="storyCampaignSection storyCampaignArcLink" type="button" id="opsArcsToDossier">'
      +'<span>FOUR FACTION ENDGAMES</span><small>Read the long-form arcs in the Dossier →</small></button>';
  pane.querySelectorAll('.storyCampaignAction').forEach(b=>{
    const go=()=>storyCampaignOpenMission(b.dataset.campaignMission);
    if(typeof mfBindTap==='function') mfBindTap(b,go); else b.addEventListener('click',go);
  });
  const arcLink=document.getElementById('opsArcsToDossier');
  if(arcLink){
    const goD=()=>{ if(typeof sfx==='function') sfx('ui');
      /* renderCodex is what main.js calls to fill the Dossier — the codex is
         the faction screen since issue 10 folded dispatches into the mailbox. */
      if(typeof renderCodex==='function') renderCodex();
      if(typeof showFrontScreen==='function') showFrontScreen('dossierScr'); };
    if(typeof mfBindTap==='function') mfBindTap(arcLink,goD); else arcLink.addEventListener('click',goD);
  }
  if(typeof opsSyncGo==='function') opsSyncGo();
}
/* The operation the CAMPAIGN tab would start: the first unlocked mission the
   player has not cleared. This is what the pinned footer button launches, so
   that tab obeys the same rule as Weekly without burying a button per row. */
function storyCampaignNextMission(){
  const p=storyCampaignProgress();
  const m=STORY_CAMPAIGN_PROLOGUE[p.current];
  return (m&&p.states[p.current]&&p.states[p.current].open)?m.id:null;
}
function storyCampaignStartNext(){
  const id=storyCampaignNextMission();
  if(!id){ if(typeof toast==='function') toast('Every prologue mission is cleared — pick one from the ladder to replay'); return false; }
  storyCampaignOpenMission(id); return true;
}
function storyCampaignToggle(sel,match){
  document.querySelectorAll(sel).forEach(b=>b.classList.toggle('on',match(b)));
}
function storyCampaignSyncSetup(){
  const setup=document.getElementById('setupScr');
  if(setup){
    setup.dataset.tab='map'; setup.classList.remove('setupAll');
    setup.querySelectorAll('.setupTabBtn').forEach(b=>b.classList.toggle('on',b.dataset.tab==='map'));
    const adv=document.getElementById('advToggle'); if(adv){adv.classList.remove('on');adv.textContent='SHOW ALL';}
  }
  if(typeof renderFacRow==='function') renderFacRow();
  storyCampaignToggle('.glbtn',b=>b.dataset.g===goalSel);
  storyCampaignToggle('.tmbtn',b=>+b.dataset.t===timeLimit);
  storyCampaignToggle('.pcbtn',b=>+b.dataset.p===resPace);
  storyCampaignToggle('.crbtn',b=>+b.dataset.c===crateRate);
  storyCampaignToggle('.bsbtn',b=>b.dataset.bs===battlefieldPreset);
  storyCampaignToggle('.ifbtn',b=>!!+b.dataset.i===infestationOn);
  storyCampaignToggle('.globalDiff',b=>+b.dataset.d===difficulty);
  if(typeof renderPlanetRow==='function') renderPlanetRow();
  storyCampaignToggle('#facRow .fbtn',b=>b.dataset.f===aiFactionSel);
  storyCampaignToggle('#pfacRow .fbtn',b=>b.dataset.f===playerFaction);
  storyCampaignToggle('.dfbtn',b=>+b.dataset.df===defenseFocus);
  storyCampaignToggle('.wbtn',b=>+b.dataset.w===wcChoice);
  const goal=document.getElementById('goalHint'); if(goal) goal.textContent=goalDef().ds;
  const scale=document.getElementById('battleScaleHint'),scaleDef=battlefieldPresetDef();
  if(scale) scale.textContent=scaleDef.km+' — '+scaleDef.ds;
  const infestation=document.getElementById('infestHint'); if(infestation) infestation.textContent=infestationOn
    ?'Neutral nests spread and erupt during the battle.'
    :'No neutral nests, infestation guards, eruptions, spread, or map-wide tides.';
  const defence=document.getElementById('defFocusHint'); if(defence) defence.textContent=defenseFocus
    ?'Tower defence: stronger, longer-ranged fortifications against faster enemy pressure.'
    :'Classic RTS balance between mobile armies and static defences.';
  if(typeof renderMapRow==='function') renderMapRow();
  if(typeof renderSpawnPlanner==='function') renderSpawnPlanner();
}
let storyCampaignActiveId='',storyCampaignResultRecorded=false,storyCampaignRuntime=null;
function storyCampaignOpenMission(missionId){
  const i=STORY_CAMPAIGN_PROLOGUE.findIndex(m=>m.id===missionId),m=STORY_CAMPAIGN_PROLOGUE[i];
  if(!m||!storyCampaignUnlocked(m,i)) return;
  if(m.goal==='training'){
    storyCampaignActiveId=''; storyCampaignRuntime=null;
    const debug=window.__tutDebug&&window.__tutDebug();
    if(debug&&typeof debug.startTraining==='function'){
      if(typeof initAudio==='function') initAudio();
      debug.startTraining(); return;
    }
    if(typeof toast==='function') toast('Training systems are still loading — try again in a moment.');
    return;
  }
  /* wcChoice=0 alone was not enough: pickWildcards prefers explicitly CHOSEN
     ids, and META.opmods keeps whatever the player last armed for their own
     skirmishes — so an authored prologue mission quietly ran with Brittle
     Frames or Iron Enemy attached and nothing on the card admitted it. An
     authored mission is authored: it brings its own modifiers or none. */
  /* Borrow the WHOLE plan before writing any of it. Only META.opmods used to be
     held, so the other fourteen fields below were a permanent clobber of the
     player's own skirmish setup — and one prologue mission is authored on
     theme:'arctic', which is how a player who opened it once found every
     later battle and the menu diorama frozen in the snow biome. */
  storyCampaignBorrowPlan();
  storyCampaignActiveId=m.id; storyCampaignResultRecorded=false; storyCampaignRuntime=null;
  activeWarMode='campaign';
  difficulty=m.diff; defenseFocus=m.defense?1:0; infestationOn=!!m.inf; wcChoice=0;
  META.opmods=Object.assign({},m.mods||{});
  goalSel=m.goal; timeLimit=m.time; resPace=1; crateRate=crateRateBase=1;
  curMap=m.map; curTheme=m.theme; battlefieldPreset=m.scale;
  aiFactionSel=storyCampaignFac(m).key; playerFaction=m.player||'nova'; playerStartZone='sw'; spawnPick='player';
  aiSlots.forEach((A,n)=>{A.on=n===0;A.diff=m.diff;A.zone=n===0?'ne':n===1?'nw':'se';A.ally=false;A.behavior=m.behavior||'balanced';});
  storyCampaignSyncSetup();
  if(typeof renderOps==='function') renderOps();
  if(typeof initAudio==='function') initAudio();
  if(typeof sfx==='function') sfx('confirm');
  if(typeof showFrontScreen==='function') showFrontScreen('setupScr');
  /* Campaign missions already own their map and rules. Enter the final brief
     directly instead of making the player re-select the authored planet and
     region through the Standard conquest route. */
  if(typeof mfGalaxySetStage==='function')mfGalaxySetStage('deploy');
  const scroll=document.querySelector('#setupScr .setupScroll'); if(scroll) scroll.scrollTop=0;
  if(typeof toast==='function') toast(m.code+' · '+m.ttl+' — deployment preset loaded');
}

/* THE PLAYER'S OWN DEPLOYMENT PLAN, held while an authored mission borrows it.
   These are all top-level `let` bindings in the shared scope, not window
   properties, so the snapshot has to name them one at a time — a loop over
   string keys silently reads undefined and hands back a wiped plan. */
let storyCampaignPrevPlan=null;
function storyCampaignBorrowPlan(){
  if(storyCampaignPrevPlan) return false;          // already borrowed; don't re-snapshot a mission
  storyCampaignPrevPlan={
    activeWarMode:activeWarMode,
    difficulty:difficulty, defenseFocus:defenseFocus, infestationOn:infestationOn,
    wcChoice:wcChoice, goalSel:goalSel, timeLimit:timeLimit,
    resPace:resPace, crateRate:crateRate, crateRateBase:crateRateBase,
    curMap:curMap, curTheme:curTheme, battlefieldPreset:battlefieldPreset,
    aiFactionSel:aiFactionSel, playerFaction:playerFaction,playerCommanderId:playerCommanderId,
    playerStartZone:playerStartZone, spawnPick:spawnPick,
    aiSlots:aiSlots.map(A=>({on:A.on,diff:A.diff,zone:A.zone,ally:!!A.ally,behavior:A.behavior||'balanced'})),
    opmods:Object.assign({},META.opmods||{})
  };
  return true;
}
function storyCampaignRestorePlan(){
  const p=storyCampaignPrevPlan;
  if(!p) return false;
  storyCampaignPrevPlan=null;
  activeWarMode=p.activeWarMode||'standard';
  difficulty=p.difficulty; defenseFocus=p.defenseFocus; infestationOn=p.infestationOn;
  wcChoice=p.wcChoice; goalSel=p.goalSel; timeLimit=p.timeLimit;
  resPace=p.resPace; crateRate=p.crateRate; crateRateBase=p.crateRateBase;
  curMap=p.curMap; curTheme=p.curTheme; battlefieldPreset=p.battlefieldPreset;
  aiFactionSel=p.aiFactionSel; playerFaction=p.playerFaction;playerCommanderId=p.playerCommanderId;
  playerStartZone=p.playerStartZone; spawnPick=p.spawnPick;
  aiSlots.forEach((A,n)=>{ const s=p.aiSlots[n]; if(s){ A.on=s.on; A.diff=s.diff; A.zone=s.zone; A.ally=!!s.ally;A.behavior=s.behavior||'balanced'; } });
  META.opmods=p.opmods;
  if(typeof metaSave==='function') metaSave();
  /* The menu diorama caches the built theme, so handing curTheme back is not
     enough on its own — the backdrop has to be told to rebuild. */
  if(typeof applyTheme==='function') applyTheme();
  storyCampaignActiveId=''; storyCampaignRuntime=null; storyCampaignResultRecorded=false;
  return true;
}
/* Kept as the name main.js's return-to-menu hook already calls. */
function storyCampaignRestoreMods(){ return storyCampaignRestorePlan(); }
function storyCampaignPlanBorrowed(){ return !!storyCampaignPrevPlan; }

/* ---- Authored mission runtime -------------------------------------------
   Operations still use the real simulation, but an authored mission may add a
   small deterministic layer: a named field objective and timed pressure beats.
   This is deliberately data-light so it can coexist with save/session recovery
   and later move behind the co-op command protocol without rewriting combat. */
function storyCampaignMission(){
  return STORY_CAMPAIGN_PROLOGUE.find(m=>m.id===storyCampaignActiveId)||null;
}
function storyCampaignOnDeploy(){
  const m=storyCampaignMission(); if(!m||m.script!=='mosswatch')return;
  const px=carrier.x+(MAP*.5-carrier.x)*.62,py=carrier.y+(MAP*.5-carrier.y)*.62;
  let L=findLand(px,py);
  if(typeof battlefieldClampPoint==='function')L=battlefieldClampPoint(L[0],L[1],48);
  const kind={id:'campaign_cache',em:'◇',nm:'Mosswatch Survey Archive',
    ds:'Research Data and one crafting-material recovery',rarity:3,w:0,col:[92,228,255],spr:'crystal'};
  const C=spawnCrate(L[0],L[1],kind); C.alt=0;C.site=true;C.siteName='NOVA SURVEY ARCHIVE';C.mission=true;
  stats.campaignCache=0;
  storyCampaignRuntime={id:m.id,cache:C,cacheCollected:false,beat:0};
  if(typeof mmPing==='function')mmPing(C.x,C.y,'new_enemy');
  toast('◇ OPTIONAL OBJECTIVE — recover the Mosswatch survey archive');
}
function storyCampaignSpawnBrood(count,caster){
  const base=(typeof AI!=='undefined'&&AI.base)?AI.base:{x:MAP*.75,y:MAP*.25};
  let L=findLand(base.x+(MAP*.5-base.x)*.18,base.y+(MAP*.5-base.y)*.18);
  if(typeof battlefieldClampPoint==='function')L=battlefieldClampPoint(L[0],L[1],120);
  const from={x:L[0],y:L[1]};
  const tx=heroIdx>=0?ux[heroIdx]:carrier.x,ty=heroIdx>=0?uy[heroIdx]:carrier.y;
  /* Arrival is a wound, not a dropship or burrow. The doubled violet/red bloom,
     torn terrain and sub-bass impact establish the soul-plane transition before
     the first body exists, so the faction's origin is readable in play. */
  deformTerrain(from.x,from.y,105,.07);addCrater(from.x,from.y,72);
  for(let q=0;q<34;q++){
    const a=q/34*TAU,sp=65+Math.random()*150;
    addParticle(q%3===0?3:0,from.x,from.y,Math.cos(a)*sp,Math.sin(a)*sp,.7+Math.random()*.8,7+Math.random()*17,
      q%2?184:255,q%2?72:42,q%2?255:96);
  }
  shake=Math.max(shake,13);sfx('boom',from.x,from.y,1.7);
  if(storyCampaignRuntime){storyCampaignRuntime.rifts=storyCampaignRuntime.rifts||[];storyCampaignRuntime.rifts.push({x:from.x,y:from.y,t:stats.t});}
  for(let n=0;n<count;n++){
    const type=caster&&n===0?UT_BROOD_CASTER:(n%7===0?13:12);
    const i=spawnUnit(type,2,from.x+rr(-105,105),from.y+rr(-105,105));
    if(i<0)continue;
    ustate[i]=2;utx[i]=tx+rr(-85,85);uty[i]=ty+rr(-85,85);umarch[i]=1;
    if(type===UT_BROOD_CASTER)ubroodLed[i]=3;
  }
  if(typeof setWaveWarning==='function')setWaveWarning(from.x,from.y,tx,ty,9,2+(storyCampaignRuntime?storyCampaignRuntime.beat:0),count);
  if(typeof showAlert==='function')showAlert(from.x,from.y,'new_enemy');
}
function storyCampaignTick(){
  const R=storyCampaignRuntime,m=storyCampaignMission();
  if(!R||!m||!matchLive||m.script!=='mosswatch')return;
  if(R.beat===0&&stats.t>=75){
    R.beat=1;storyCampaignSpawnBrood(12,false);
    toast('KEEL: Reality fracture on the north approach. Hold the causeway.');
  }else if(R.beat===1&&stats.t>=190){
    R.beat=2;storyCampaignSpawnBrood(29,true);
    toast('KEEL: Critical biomass detected — Tidecaster assault inbound.');
  }
}
const STORY_CAMPAIGN_APPLY_CRATE_BASE=applyCrate;
applyCrate=function(k,x,y){
  if(k&&k.id==='campaign_cache'){
    const data=CRATE_KINDS.find(q=>q.id==='data'),mats=CRATE_KINDS.find(q=>q.id==='mats');
    if(data)STORY_CAMPAIGN_APPLY_CRATE_BASE(data,x,y);
    if(mats)STORY_CAMPAIGN_APPLY_CRATE_BASE(mats,x,y);
    stats.campaignCache=1;
    if(storyCampaignRuntime)storyCampaignRuntime.cacheCollected=true;
    toast('◇ OPTIONAL OBJECTIVE COMPLETE — archive and fabrication sample secured');
    return;
  }
  STORY_CAMPAIGN_APPLY_CRATE_BASE(k,x,y);
};
const STORY_CAMPAIGN_AI_TICK_BASE=aiTick;
aiTick=function(dt){STORY_CAMPAIGN_AI_TICK_BASE(dt);storyCampaignTick();};

/* Mission records are independent from faction win counters. Replaying a
   skirmish against the same faction cannot unlock campaign chapters, while old
   clears remain readable through the explicit legacy migration above. */
const STORY_CAMPAIGN_META_GRANT_BASE=metaGrant;
metaGrant=function(win){
  const rw=STORY_CAMPAIGN_META_GRANT_BASE(win),m=storyCampaignMission();
  if(!m||storyCampaignResultRecorded)return rw;
  storyCampaignResultRecorded=true;
  META.campaign=META.campaign||{missions:{}};META.campaign.missions=META.campaign.missions||{};
  const rec=META.campaign.missions[m.id]||{attempts:0,wins:0,bestTime:0};
  rec.attempts=(rec.attempts||0)+1;rec.lastPlayed=Date.now();rec.lastWin=!!win;
  if(win){
    rec.wins=(rec.wins||0)+1;rec.completedAt=rec.completedAt||Date.now();
    rec.bestTime=rec.bestTime?Math.min(rec.bestTime,stats.t|0):(stats.t|0);
    if(m.script==='mosswatch'){
      const bonus=Math.max(1,Math.round((rw.data||0)*.15));
      META.researchData=(META.researchData||0)+bonus;rw.data=(rw.data||0)+bonus;
      rw.dataParts=(rw.dataParts||[]).concat([['Campaign intelligence +15%',bonus]]);
      rec.optionalCache=!!(stats.campaignCache||0);
    }
  }
  META.campaign.missions[m.id]=rec;
  metaSave();if(typeof syncPush==='function')syncPush();
  return rw;
};
/* story.js loads after endgame.js, so the wrapper is installed before initOps
   binds its tab listener. tutorial.js later wraps this wrapper in turn; both
   additions therefore survive without either feature editing the other. */
const STORY_CAMPAIGN_RENDER_OPS_BASE=renderOps;
renderOps=function(){
  storyCampaignEnsureOps();
  STORY_CAMPAIGN_RENDER_OPS_BASE();
  storyCampaignRender();
};
const STORY_CAMPAIGN_RENDER_BRIEF_BASE=renderOpsBrief;
renderOpsBrief=function(mode){
  STORY_CAMPAIGN_RENDER_BRIEF_BASE(mode);
  if(mode!=='campaign') return;
  const p=storyCampaignProgress(),set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  set('opsBriefThreat','P0'); set('opsBriefThreatNm','PLAYABLE PROLOGUE');
  set('opsBriefMods',p.done+'/'+STORY_CAMPAIGN_PROLOGUE.length); set('opsBriefModsNm','MISSIONS CLEARED');
  set('opsBriefPayout','LIVE'); set('opsBriefState','PRE-ALPHA');
};

/* ============================================================================
   COMMANDER LORE AND DIALOGUE COPY
   ----------------------------------------------------------------------------
   Narrative copy for the nine playable commanders, kept here with the rest of
   the written game rather than beside the cooldown arithmetic in
   src/game/commander.js. That file owns the identity DESCRIPTOR (who a
   commander is, mechanically) and the dialogue EVENT system (when a line is
   allowed to fire). This section owns what the line actually says.

   Two products live here:

     1. COMMANDER_LORE — biography, service record and epithet, addressed by the
        descriptor's loreKey. storySpeakerVisual() above already treats the
        commander portrait as a canonical command identity; this is the same
        identity in prose.

     2. Dialogue lines, resolved in three tiers by commanderDialogueLines():
          commander override  -> COMMANDER_LORE[key].lines
          faction doctrine    -> COMMANDER_DOCTRINE_LINES[faction]
          neutral template    -> COMMANDER_DOCTRINE_LINES.default
        A missing tier falls through rather than erroring, so a new commander
        speaks in their faction's voice from the moment they exist and gains
        personal lines later as they are written.

   THIS IS TEXT ONLY. No audio is authored, generated or referenced here: the
   subtitle is the deliverable, and a matching recording would be a voice-bank
   data change (see the COMMANDER VOICE block in src/audio.js). Lines are
   written to read correctly with no sound at all.

   The cue builder in commander.js expands {cdr} to the commander's short name
   and {fac} to the faction display name. This file stays pure data and does not
   expand anything itself. */
